let post;
try {
  post = await generateBlogPost(topic);
} catch (err) {
  console.error("Blog post generation failed:", err);
  const slug = topic
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .slice(0, 60);
  const placeholder = `---
title: "${topic}"
pubDate: "${new Date().toISOString().slice(0, 10)}"
draft: true
_note: "Auto-generation failed. Review and complete before publishing."
---

Placeholder created by fallback handler. Joel: add content here before removing the draft flag.
`;
  await fs.writeFile(`src/content/blog/${slug}.md`, placeholder, "utf8");
  process.exit(0);
}
await writePostFile(post);
